  ["highground.coachbounties.sample_event_your_target_is_nearby.f5e819"] = "예제 이벤트: 대상이 가까이 있음",
  ["highground.coachbounties.a_sighting_detects_value2_the_same_target.a41058"] = "{value2}을 발견했어요 당신이 추적하려고 선택한 목표물이죠 이 알림을 닫아 예시 킬을 계속하거나 포스터를 다시 검사하십시오.",
  ["highground.coachbounties.close_the_wanted_alert_or_next_to.724954"] = "현상 수배 알림을 닫거나 다음 을 눌러 닫기 버튼을 활성화합니다.",
  ["highground.coachbounties.sample_event_the_target_is_killed.ca18c1"] = "예제 이벤트: 대상이 사망함",
  ["highground.coachbounties.the_addon_creates_the_report_automatically_a.1fa40f"] = "애드온은 보고서를 자동으로 생성합니다. 판독 가능한 죽음의 충격이 확인되고, 명예 크레딧은 보조를 포함할 수 있습니다. 스크린샷 체크 표시는 이미지가 저장되었음을 의미합니다. 검토를 따르려면 보고서를 엽니다.",
  ["highground.coachbounties.click_view_sample_report_copying_proof_is.ecb999"] = "예시 보고서 보기 를 클릭합니다. 복사 증명은 선택 사항입니다; 실제 스크린 샷이나 보고서가 전송되지 않습니다.",
  ["highground.coachbounties.bounty_ignored.3d5adf"] = "현상금 무시됨",
  ["highground.coachbounties.follow_your_own_claim.e2d148"] = "자신의 청구를 따르십시오",
  ["highground.coachbounties.this_target_was_not_added_to_your.871630"] = "이 대상은 추적 보상에 추가되지 않았습니다. 당신이 청구를 시도 할 때마다 사냥 경로를 다시 시작합니다.",
  ["highground.coachbounties.your_report_is_saved_its_next_step.c8431b"] = "보고서가 저장되었습니다. 다음 단계는 배달, 검토 또는 지불을 설명합니다. 게시자는 보상을 검토하고 게임을 통해 지불합니다. 감지가 사망을 놓친 경우에만 보상 요구 또는 누락된 킬 보고를 사용합니다.",
  ["highground.coachbounties.done_returns_to_the_two_bounty_paths.aa70f3"] = "완료는 두 현상금 경로로 돌아갑니다. 실제 보고서, 스크린 샷 또는 메시지가 전송되지 않았습니다.",
  ["highground.coachbountysamples.nightshade_vale.0d981c"] = "나이트셰이드 베일",
