  ["highground.coachbountysamples.this_sample_kill_is_already_submitted_view.e01249"] = "이 예시 킬은 이미 제출되었습니다. 검토를 따르려면 청구 보기 를 클릭합니다.",
  ["highground.coachbountysamples.sample_kill_submitted_awaiting_the_poster_s.5a1179"] = "예시 킬 제출 · 게시자의 검토를 기다리고 있습니다. Open View는 보고서를 따를 것이라고 주장합니다.",
