  ["highground.coachexamples.use_replay_to_bring_this_control_back.83c8a3"] = "재생 을 사용하여 이 컨트롤을 다시 보여줍니다.",
  ["highground.coachmap.a_teammate.aa3d91"] = "팀 동료",
  ["highground.coachmap.silverwing_hold.e68140"] = "실버윙 홀드",
  ["highground.coachmap.enemies_on_your_world_map.7062f3"] = "세계지도에 있는 적들",
  ["highground.coachmap.this_is_wow_s_world_map_with.e5b392"] = "WoW 세계 지도에 전쟁노래 협곡의 예시 적 다섯 명이 표시됩니다. 경기 중에는 같은 핀이 전장 지도(Shift+M)에도 나타납니다. 관찰된 적만 위치가 표시됩니다.",
  ["highground.coachmap.warsong_gulch_is_unavailable_in_this_client.da444f"] = "워송 굴치는 이 클라이언트에서 사용할 수 없습니다. 이것은 일반적인 세계지도입니다. Guides로 돌아가 다른 기능을 시도하십시오.",
  ["highground.coachmap.start_with_a_fresh_sighting.d7f307"] = "신선한 관찰로 시작하세요",
  ["highground.coachmap.this_bright_rogue_pin_is_a_fresh.bbd705"] = "이 밝은 로거 핀은 신선한 관찰입니다. 마우스 오버하면 누가 보았고 누가 관찰했는지 읽을 수 있습니다.",
  ["highground.coachmap.hover_the_highlighted_enemy_then_choose_next.7c672d"] = "강조된 적을 마우스 오른쪽으로 이동한 다음 다음을 선택합니다.",
  ["highground.coachmap.spot_the_suggested_target.2d4580"] = "제안된 목표물 찾기",
  ["highground.coachmap.the_outer_ring_marks_the_suggested_target.9f5fc2"] = "바깥쪽 링은 제안된 목표를 표시합니다. 클래스 아이콘은 어떤 종류의 적이 관찰되었는지 알려줍니다.",
  ["highground.coachmap.older_sightings_fade.039a3d"] = "오래된 관측 페이드",
  ["highground.coachmap.this_faded_mage_was_last_seen_36.2fe437"] = "이 희미해진 마법사는 36초 전에 마지막으로 보였습니다. 시간은 관측의 나이입니다. 그들은 이동할 수 있습니다; 이것은 라이브 위치가 아닙니다.",
  ["highground.coachmap.a_location_can_be_approximate.08cdfb"] = "위치는 대략적일 수 있습니다.",
  ["highground.coachmap.a_faint_circle_marks_roughly_where_an.47c0a0"] = "정확한 위치를 모를 때(예: 알려진 지역) 흐린 원이 적이 마지막으로 보인 대략적인 위치를 표시합니다. 마우스를 올리면 누가 언제 보였는지 확인할 수 있습니다. 아군의 관측으로 보이지 않는 적을 드러내지 않고 원을 좁힐 수 있습니다.",
  ["highground.coachmap.use_the_whole_picture.b9e5f8"] = "전체 그림 사용",
  ["highground.coachmap.compare_fresh_pins_older_sightings_and_the.a2fa1f"] = "경로를 선택하기 전에 신선한 핀, 이전 관측 및 목표를 비교하십시오. 이러한 예시 관측은 라이브 추적 및 그룹 공유에서 제외됩니다. 완료 는 이전 지도를 복원합니다.",
  ["highground.coachmap.warsong_gulch_is_unavailable_in_this_client.ccb80d"] = "워송 굴치는 이 클라이언트에서 사용할 수 없습니다. 안내선을 사용하여 돌아갑니다.",
  ["highground.coachmap.use_replay_to_reopen_warsong_gulch_on.5dd141"] = "리플레이를 사용하여 세계지도에서 워송 굴치를 다시 열 수 있습니다.",
  ["highground.coachpreferences.changes_here_save_immediately.a4d86e"] = "여기에서 변경된 내용은 즉시 저장됩니다.",
  ["highground.coachpreferences.open_this_addon_s_appearance.f257e1"] = "이 추가 기능 열기",
  ["highground.coachpreferences.open_shared_appearance.31a605"] = "공유 모양 열기",
  ["highground.coachpreferences.click_appearance_under_battlegrounds_to_adjust_enemy.54bf82"] = "전장 아래의 모양을 클릭하여 적 행과 대상 표시자를 조정합니다.",
  ["highground.coachpreferences.shared_appearance_controls_the_theme_fonts_and.47799d"] = "공유 외관은 활성화된 모든 애드온의 테마, 글꼴 및 접근성을 제어합니다.",
  ["highground.coachpreferences.click_appearance_under_battlegrounds.189abb"] = "Battlegrounds 아래에서 모양을 클릭합니다.",
  ["highground.coachpreferences.click_shared_appearance.962763"] = "공유 모양 을 클릭합니다.",
  ["highground.coachpreferences.choose_a_shared_theme.8b4434"] = "공유 테마 선택하기",
  ["highground.coachpreferences.theme_and_accessibility_apply_to_every_addon.aba586"] = "테마 및 접근성은 모든 애드온에 적용됩니다. 개별 패널 컨트롤은 애드온의 자신의 섹션에 남아 있습니다.",
  ["highground.coachpreferences.fine_tune_this_addon_s_panels.60828e"] = "이 추가 기능의 패널 미세 조정",
  ["highground.coachpreferences.fine_tune_shared_styling.b1faf5"] = "공유 스타일링 미세 조정",
  ["highground.coachpreferences.these_dimensions_and_row_details_belong_to.538aec"] = "이 치수와 행 세부 정보는 Battlegrounds에 속합니다. 투기장과 근처에는 독립적인 외관 페이지가 있습니다.",
  ["highground.coachpreferences.bar_textures_colours_and_borders_are_shared.cbec37"] = "바 텍스처, 색상 및 테두리가 공유됩니다. 자체 애드온의 Appearance 페이지에서 각 패널의 크기를 조정합니다.",
  ["highground.coachpreferences.settings_live_with_their_addon.f2c359"] = "설정은 그들의 추가 기능과 함께 살고",
  ["highground.coachpreferences.use_an_addon_s_settings_appearance_commands.b1a987"] = "애드온의 설정, 외관, 명령, 미리보기 및 가이드 페이지를 사용합니다. 배틀그라운드 패널은 /hg bg test을 사용합니다. 도움말 및 명령에서 /hg test 또는 /hg test stop를 실행하여 모든 미리보기를 전환하거나 중지합니다. 개요 및 재로드 후 애드온이 실행되는지 여부를 제어합니다. 공유 환경설정은 모든 추가 기능에 영향을 줍니다.",
  ["highground.coachpreferences.keep_the_panels_you_want.abbf0b"] = "원하는 패널 유지",
  ["highground.coachpreferences.choose_shared_preferences.f69dd0"] = "공유 환경설정 선택하기",
  ["highground.coachpreferences.checked_means_enabled_all_available_feature_switches.16b69f"] = "체크된 것은 활성화되었음을 의미합니다. 사용 가능한 모든 기능 스위치가 여기에 표시되며 나머지는 스크롤하여 볼 수 있습니다.",
  ["highground.coachpreferences.checked_means_enabled_this_switch_shows_the.de650b"] = "체크된 것은 활성화되었음을 의미합니다. 이 스위치는 Highground 미니맵 버튼을 표시합니다.",
  ["highground.coachpreferences.choose_the_warnings_you_want.2794f4"] = "원하는 경고 선택",
  ["highground.coachpreferences.essentials_is_a_starting_point_text_only.1f45b3"] = "Essentials는 출발점입니다. 텍스트는 쓰여진 알림만 유지하고 알림 소리를 음소거합니다.",
  ["highground.coachpreferences.this_changes_your_real_alert_preference.ecd3f5"] = "이것은 실제 알림 기본 설정을 변경합니다.",
  ["highground.coachpreferences.go_straight_to_an_addon_s_alerts.46dd58"] = "애드온의 알림으로 바로 이동",
  ["highground.coachpreferences.the_battlegrounds_nearby_and_bounties_links_open.676c0b"] = "전장, 인근 및 보상 링크는 텍스트 및 사운드 컨트롤을 직접 엽니다. 비활성화된 추가 기능은 추가 기능에서 활성화하고 재로드한 후 사용할 수 있습니다.",
  ["highground.coachpreferences.click_battlegrounds_or_next_to_open_its.68ede3"] = "전장 을 클릭하거나 다음 을 클릭하여 알림 컨트롤을 엽니다.",
  ["highground.coachpreferences.enemy_stealth_stays_available_here_even_when.63bf57"] = "적 스텔스는 애드온이 비활성화된 경우에도 여기에서 사용할 수 있습니다.",
  ["highground.coachpreferences.choose_text_sound_or_both.306e9e"] = "텍스트, 사운드 또는 둘 다 선택",
  ["highground.coachpreferences.these_switches_belong_to_battlegrounds_settings_nearby.0373c0"] = "이 스위치들은 배틀그라운드 설정에 속합니다. 근처와 현상금은 그들 자신을 가지고있다. 공유 알림 레벨과 마스터 사운드는 여전히 적용됩니다.",
  ["highground.coachpreferences.enemy_stealth_applies_across_addons_other_alert.fa92cd"] = "적 스텔스는 애드온에 적용됩니다. 다른 알림 카테고리는 그들의 애드온의 설정에 살고 있습니다. 공유 알림 레벨과 마스터 사운드는 여전히 적용됩니다.",
  ["highground.coachpreferences.highground_is_the_only_download_you_need.f138df"] = "Highground은 필요한 유일한 다운로드입니다.",
  ["highground.coachpreferences.addons_brings_the_addon_switches_settings_shortcuts.df8aff"] = "Addons는 애드온 스위치, 설정 단축키 및 가이드를 함께 제공합니다. 별도의 독립형 다운로드를 제거합니다. 모든 모듈 폴더와 필요한 데이터 애드온을 보관하십시오. 데이터 애드온을 비활성화하면 Highground이 로드되지 않습니다.",
  ["highground.coachpreferences.a_disabled_module_does_not_activate_a.e4cf84"] = "비활성화된 모듈은 독립형 복사본을 활성화하지 않습니다. 이 가이드에 의해 아무것도 제거되지 않습니다.",
  ["highground.coachpreferences.choose_which_addons_run.892aae"] = "어떤 추가 기능을 실행할지 선택하기",
  ["highground.coachpreferences.enable_addon_is_the_same_per_character.e05474"] = "애드온 활성화는 WoW 애드온 목록과 같은 캐릭터별 스위치입니다. Highground 다운로드에는 여섯 개의 하위 애드온이 모두 포함되어 있습니다.",
  ["highground.coachpreferences.these_are_real_switches_you_can_continue.862243"] = "이것은 진짜 스위치입니다. 아무것도 변경하지 않고 계속할 수 있습니다.",
  ["highground.coachpreferences.visit_settings_or_replay_a_guide.e879b6"] = "설정 방문 또는 가이드 재생하기",
  ["highground.coachpreferences.visit_opens_this_addon_s_overview_and.64e863"] = "방문 이 애드온의 개요 및 설정을 엽니다. 시작, 재개 또는 재생은 워크스루를 열고 저장된 위치를 유지합니다.",
  ["highground.coachpreferences.visit_leaves_this_walkthrough_next_continues_without.da36c5"] = "방문은 이 워크스루를 떠납니다. 다음은 방문하지 않고 계속됩니다.",
  ["highground.coachpreferences.recognize_subaddons_in_the_sidebar.8ccd1c"] = "사이드바에서 부분 추가 기능 인식",
  ["highground.coachpreferences.each_subaddon_has_a_small_crest_and.3b587c"] = "각각의 서브 애드온은 작은 크레스트와 악센트 스트라이프를 가지고 있습니다. 개요 및 활성화, 설정, 사용 가능한 경우 외관, 명령, 미리보기 및 가이드에 대한 섹션을 확장합니다.",
  ["highground.coachpreferences.shared_preferences_saved_setups_and_help_apply.3e1969"] = "공유 환경설정, 저장된 설정 및 도움말은 개별 애드온을 넘어 적용됩니다.",
  ["highground.coachpreferences.keep_your_settings_when_disabling_an_addon.518274"] = "애드온을 비활성화할 때 설정 유지",
  ["highground.coachpreferences.changing_a_switch_takes_effect_after_reload.145c67"] = "스위치를 변경하면 재로드 후에 효과가 나타납니다. 저장된 패널 환경설정 및 기록은 그대로 유지됩니다. 인근 및 투기장 카드에서 패널 표시는 패널 환경설정만 변경합니다. 재로드하기 전에 다시 추가 기능 활성화를 변경하면 변경 사항이 취소됩니다.",
  ["highground.coachpreferences.profiles_do_not_enable_or_disable_addons.a7920d"] = "프로필은 추가 기능을 활성화하거나 비활성화하지 않습니다.",
  ["highground.coachpreferences.reload_when_you_are_ready.225a57"] = "준비가 되면 다시 로드",
  ["highground.coachpreferences.after_changing_a_switch_reload_to_apply.8a851b"] = "스위치를 변경한 후 Addons에 적용하려면 다시 로드 라는 메시지가 나타납니다. 활성화된 모듈을 시작하고 비활성화된 모듈을 중지하려면 전투 외부에서 재장전합니다. 가이드는 자동으로 재로드되지 않습니다.",
  ["highground.coachpreferences.next_continues_without_reloading.acc474"] = "다음은 재로드하지 않고 계속됩니다.",
  ["highground.coachpreferences.find_commands_and_their_controls.a1ca25"] = "명령 및 컨트롤 찾기",
  ["highground.coachpreferences.each_addon_has_a_commands_page_help.cc07e2"] = "각 애드온은 명령 페이지가 있습니다; 도움말과 명령을 결합합니다. 각 명령은 하나의 행을 사용합니다. 전체 문법과 별칭을 보려면 마우스를 올려 보세요. 버튼은 설정을 열고 동작을 실행하거나 값에 대한 레이블이 있는 필드를 엽니다.",
  ["highground.coachpreferences.browsing_is_safe_action_buttons_can_change.33ba22"] = "브라우징은 안전합니다. 작업 버튼은 실제 설정을 변경할 수 있으며, 이 가이드에서는 클릭하지 않습니다.",
  ["highground.coachpreferences.discover_channel_members.5df463"] = "채널 멤버 찾기",
  ["highground.coachpreferences.your_own_character_counts_immediately_a_complete.2a1246"] = "당신 자신의 캐릭터는 즉시 계산됩니다. 완전한 채널 회원 목록은 그들의 애드온 발표가 도착하기 전에 다른 회원을 추가합니다. Refresh members는 로더를 표시하고 기다리는 동안 비활성 상태로 유지됩니다. 예시 출발을 보려면 그것을 시도하십시오.",
  ["highground.coachpreferences.this_sample_does_not_request_a_live.d4e060"] = "이 예시는 라이브 회원 목록을 요청하거나 메시지를 보내지 않습니다.",
  ["highground.coachpreferences.membership_and_version_reports_are_different.84c36a"] = "회원 및 버전 보고서가 다릅니다.",
  ["highground.coachpreferences.a_channel_member_may_not_have_a.590af5"] = "채널 회원은 응답하는 애드온을 가지고 있지 않을 수 있습니다. 공지가 없는 회원들은 자신만의 카운트를 가지고 있습니다. 버전은 수신 알림에서만 나옵니다. 추가 기능 관리자에서 업데이트 통지를 확인하십시오.",
  ["highground.coachpreferences.keep_useful_counts_when_a_list_is.120802"] = "목록을 사용할 수 없을 때 유용한 카운트 유지",
  ["highground.coachpreferences.an_incomplete_or_unavailable_member_list_keeps.d5bf62"] = "불완전하거나 사용할 수 없는 회원 목록은 마지막으로 완성된 목록을 잠시 유지한 다음 최근 발표로 돌아갑니다. 캐릭터의 숫자는 이후 탈퇴한 캐릭터도 포함할 수 있다. 그룹 및 길드 발견은 여전히 알림을 사용합니다.",
  ["highground.coachpreferences.close_the_guide_to_return_to_live.65ab77"] = "가이드를 닫아 실시간 계수로 돌아갑니다. 이 예시에서만 검색 환경설정이 비활성화됩니다.",
