  ["highground.coachrecords.turn_participation_back_on_when_you_choose.477fe0"] = "선택할 때 참여 다시 켜기",
  ["highground.coachrecords.the_same_control_turns_participation_back_on.58c9f3"] = "동일한 컨트롤은 참여를 다시 켤 수 있습니다. 조직 또는 보고서를 열어도 비활성화된 조직은 절대 활성화되지 않습니다.",
  ["highground.coachrecords.choose_your_personal_preferences.c4b70b"] = "개인 환경설정 선택",
  ["highground.coachrecords.the_preferences_tab_controls_chat_filtering_whisper.f9bdd7"] = "환경설정 탭은 이 계정의 모든 조직에 대한 채팅 필터링, 속삭임 응답 및 플레이어 도구 팁을 제어합니다. 선택한 탭은 다시 클릭할 때 열려 있습니다.",
  ["highground.coachrecords.choose_preferences_in_the_top_tabs_or.0f1f00"] = "상단 탭 또는 페이지 메뉴에서 환경설정 을 선택합니다.",
  ["highground.coachrecords.try_the_display_settings.2f58e9"] = "디스플레이 설정 시도",
  ["highground.coachrecords.these_are_the_real_settings_controls_with.05a843"] = "이들은 예시 값을 가진 실제 설정 컨트롤입니다. 스위치, 응답 빈도 또는 응답 메시지를 시도해 보십시오. 저장된 환경설정은 변경되지 않습니다.",
  ["highground.coachrecords.try_preferences_again_the_page_and_your.4c90f3"] = "환경설정을 다시 시도하십시오. 페이지와 예시 선택 사항이 열려 있습니다. 다음은 돌아오는 방법을 보여줍니다.",
  ["highground.coachrecords.return_to_your_organization.170575"] = "조직으로 돌아가기",
  ["highground.coachrecords.choose_organizations_to_return_to_the_page.cc33a5"] = "조직을 선택하여 떠난 페이지로 돌아갑니다. 그것의 조직, 검색 및 페이지링이 유지됩니다. 뒤로 및 앞으로 또한 방문한 페이지를 복원합니다.",
  ["highground.coachrecords.choose_organizations_finishing_closes_the_sample_nothing.45341c"] = "조직을 선택합니다. 마침은 예시를 닫습니다. 아무것도 전송되거나 실제 기록에 저장되지 않습니다.",
  ["highground.coachsamples.make_room_for_the_fight.155528"] = "싸움을 위한 공간을 만드세요",
  ["highground.coachsamples.these_are_your_actual_panels_with_sample.a55717"] = "이것은 예시 데이터가 포함된 실제 패널입니다. 싸움의 중심을 숨기지 않고 볼 수 있는 곳에 두세요 화살표는 패널이 이동할 때 따라갑니다.",
  ["highground.coachsamples.try_moving_a_panel.baacba"] = "패널 이동 시도",
  ["highground.coachsamples.drag_the_highlighted_header_to_reposition_its.736570"] = "강조 표시된 헤더를 드래그하여 패널의 위치를 변경합니다. 선택한 위치가 유지됩니다. 다른 패널도 헤더로 이동할 수 있습니다.",
  ["highground.coachsamples.find_the_panel_controls.6ff118"] = "패널 제어기 찾기",
  ["highground.coachsamples.hover_the_cogwheel_to_read_its_shortcuts.71abde"] = "톱니바퀴를 가리키면 단축키가 표시됩니다. 플레이 중에 잠금/잠금 해제, 빠른 컨트롤 및 관련 설정을 클릭하십시오. 이것은 실제 컨트롤입니다. 여기서 변경한 내용은 유지됩니다.",
  ["highground.coachsamples.return_to_your_normal_layout.357764"] = "일반 레이아웃으로 돌아가기",
  ["highground.coachsamples.done_removes_the_samples_and_restores_your.4be801"] = "완료 는 예시를 제거하고 이전 잠금 설정을 복원합니다. 선택한 패널 위치가 유지됩니다.",
  ["highground.coachsamples.your_next_resurrection.d9631f"] = "당신의 다음 부활",
  ["highground.coachsamples.enable_battleground_timers_in_game.e230d9"] = "게임에서 전장 타이머 활성화",
  ["highground.coachsamples.you_marks_your_graveyard_stables_here_the.13aa3a"] = "당신은 당신의 묘지를 표시합니다 : 여기에 스털링. 시계는 다음 부활 파도를 보여줍니다. 소스를 클릭하십시오.",
  ["highground.coachsamples.means_an_estimate.324005"] = "~는 추정치를 의미합니다.",
  ["highground.coachsamples.theirs_is_the_enemy_wave_ours_is.813de5"] = "THEIRS는 적의 파도이고, OURS는 또다른 친화적인 묘지입니다. -- 타이머가 알려지지 않았음을 의미합니다.",
  ["highground.coachsamples.a_base_is_changing_hands.727ef3"] = "기지가 손에 넘어가고 있어",
  ["highground.coachsamples.enable_objective_timers_in_game.015f04"] = "게임에서 목표 타이머 사용",
  ["highground.coachsamples.cap_is_the_countdown_after_a_base.cf7dc3"] = "CAP는 기지가 공격당한 후 카운트다운입니다. CAPPING은 그것을 캡처하려는 관찰된 시도를 표시합니다.",
  ["highground.coachsamples.plan_around_the_score.9c8157"] = "점수 주위에 계획",
  ["highground.coachsamples.win_estimates_the_result_from_the_current.0c4942"] = "WIN은 현재 점수와 베이스 소유권에서 결과를 추정합니다. 베이스가 손으로 바뀌면 바뀐다.",
  ["highground.coachsamples.find_the_enemy_flag_carrier.a2d424"] = "적의 깃발 운반자 찾기",
  ["highground.coachsamples.enable_flag_carrier_panel_in_game.91a521"] = "게임에서 플래그 캐리어 패널 활성화",
  ["highground.coachsamples.the_crest_on_each_carrier_s_class.0bc6ea"] = "각 운반자의 직업 아이콘에 있는 문장이 소속 진영을 보여 줍니다. Vexa는 상대 진영의 운반자입니다. 게임에서 왼쪽 클릭은 알려진 운반자를 대상으로 지정하고, 오른쪽 클릭은 주시 대상으로 지정합니다.",
  ["highground.coachsamples.meet_your_opponents.da736c"] = "상대를 만나보세요",
  ["highground.coachsamples.enable_arena_duels_in_game.1681fb"] = "게임에서 투기장 결투 활성화( D)",
  ["highground.coachsamples.this_sample_shows_a_duel_opponent_the.8b3cc3"] = "이 예시는 결투 상대를 보여줍니다. 패널은 도전이나 카운트다운 시에 나타나며, 결투가 끝나면 지워집니다.",
  ["highground.coachsamples.these_sample_arena_opponents_show_the_panel.a0ce17"] = "이 예시 투기장 상대는 경기에서 사용된 패널을 보여줍니다. 슬롯 라벨은 각 상대를 식별합니다. 듀얼은 하나의 상대와 동일한 패널을 사용합니다.",
  ["highground.coachsamples.target_now_keep_a_focus_for_later.e5ac6d"] = "지금 타겟, 나중에 주시 대상을 유지",
  ["highground.coachsamples.left_click_targets_this_opponent_right_click.e3ad6c"] = "왼쪽 클릭은 이 상대를 대상으로 하며, 오른쪽 클릭은 그 적을 주시 대상으로 지정합니다. 주시 대상을 사용하면 다른 적을 선택하는 동안 한 적을 계속 관찰할 수 있습니다. 전투 클릭은 동일한 상대에게 연결됩니다.",
  ["highground.coachsamples.read_the_available_information.0bb233"] = "사용 가능한 정보 읽기",
  ["highground.coachsamples.the_health_bar_and_row_details_show.3b37e7"] = "생명력 바와 행 세부 정보에는 클라이언트가 제공하는 정보가 표시됩니다. 시전과 군중 제어는 가능할 때 표시됩니다. 없는 정보는 알 수 없음으로 남으며, 생명력 0으로 처리되지 않습니다.",
  ["highground.coachsamples.follow_the_duel.c74373"] = "결투를 따르세요",
  ["highground.coachsamples.watch_the_escape_trinket.3999d0"] = "탈출 장신구를 주시하세요",
  ["highground.coachsamples.the_status_follows_the_challenge_countdown_and.0f2d4c"] = "상태는 도전, 카운트다운 및 싸움을 따릅니다. 현재 대상을 변경하면 결투 패널에 동일한 상대가 표시됩니다.",
  ["highground.coachsamples.the_trinket_icon_uses_client_reported_escape.c0b8c1"] = "트린켓 아이콘은 클라이언트가 보고한 탈출 정보를 사용합니다. 물음표는 타이밍을 사용할 수 없음을 의미하며, 귀걸이가 준비되었다는 것을 의미하지는 않습니다. 사용 가능한 쿨다운이 아이콘에 표시됩니다.",
  ["highground.coachsamples.keep_your_attention_on_the_fight.45d72d"] = "싸움에 집중하세요",
  ["highground.coachsamples.the_panel_follows_the_activity_and_clears.182545"] = "패널은 활동을 추적하고 결투 또는 경기장이 끝날 때 지워집니다. 완료는 이러한 예제 상대를 삭제합니다. 더 나은 위치가 필요한 경우 잠겨 있지 않은 상태에서 헤더를 이동합니다.",
  ["highground.coachsamples.enable_bounties_on_the_addons_page_then.b9de44"] = "가이드의 이 부분을 사용하려면 Addons 페이지에서 Bounties 를 활성화하고 다시 로드하세요.",
