  ["highground.coachsamples.sneakypete_was_just_observed_in_play_left.09919b"] = "스니키펫이 관찰됐어요 게임에서, 왼쪽 클릭은 대상을, 오른쪽 클릭은 이 적을 집중시킵니다.",
