  ["highground.coachsamples.check_the_name_choose_who_should_see.9a44df"] = "이름을 확인하고 보상을 보는 사람을 선택하고 보상을 입력하세요. 이것은 예시 데이터와 실제 현상금 양식입니다.",
  ["highground.coachsamples.the_bounties_guide_covers_posting_tracking_and.08e143"] = "현상금 가이드는 게시, 추적 및 청구를 다룹니다.",
  ["highground.coachsamples.bounties_is_disabled_enable_it_on_addons.764c0f"] = "Bounties가 비활성화되어 있습니다. Addons에서 활성화하고 리로드한 후 현상금을 추가해 보세요.",
  ["highground.coachtargeting.rogue_your_target.c865b1"] = "로그 · 당신의 대상",
  ["highground.coachtargeting.enemy_nameplates_are_hidden_the_sniper_marker.391350"] = "적의 명판은 숨겨져 있습니다.\n스나이퍼 마커는 보이는 명판이 필요해",
