  ["highground.coachtargeting.suggested_lunara_your_target_vexa.ca3f9d"] = "제안: Lunara · 당신의 대상: Vexa",
  ["highground.coachtargeting.recommendations_off_the_sniper_marker_follows_your.3d1a5e"] = "권장 사항 꺼짐: 저격수 마커가 목표물을 따라갑니다, 벡사.",
  ["highground.coachtargeting.the_sniper_marker_shows_the_suggestion.d28836"] = "저격수 마커가 제안을 보여줍니다",
  ["highground.coachtargeting.it_points_to_lunara_your_selected_target.7e9f71"] = "이것은 루나라를 가리킨다. 선택한 대상은 여전히 벡사입니다. 전환 여부는 여러분이 결정하십시오. 이 예시는 저장된 스타일, 색상 및 두개골 선택을 사용합니다. 전장 → 외관 → 저격수 마커는 새로운 시야 또는 레거시 크로스하이어, 별도의 색상, 배치 및 크기를 제공합니다. 머리 위치는 약간의 변화가 있다.",
  ["highground.coachtargeting.try_hg_sniper_test_on_a_target.72718a"] = "보이는 명판이 있는 대상을 /hg sniper test on으로 시도하고, 킬 윈도우 모양을 위해 /hg go을 시도하십시오. 체력이 낮으면 맥박이 빨라지고, 움직임이 줄어들면 맥박이 느려집니다. 정지하려면 /hg sniper test를 반복합니다.",
  ["highground.coachtargeting.enable_sniper_marker_in_game.53767b"] = "게임에서 저격수 마커 활성화",
  ["highground.coachtargeting.this_cross_marks_a_healer.3e70f2"] = "이 십자가는 치유자를 나타냅니다",
  ["highground.coachtargeting.the_red_cross_identifies_a_known_enemy.f8294e"] = "적십자는 알려진 적의 치유자를 나타냅니다. 친절한 치료사는 녹색 십자가를 사용합니다.",
  ["highground.coachtargeting.enable_healer_marks_in_game.8c2663"] = "게임에서 치료자 표시 사용하기",
  ["highground.coachtargeting.keep_enemy_nameplates_visible.183b52"] = "적의 명판을 보이도록 유지",
  ["highground.coachtargeting.turn_sample_nameplates_off_then_on_in.61ded4"] = "예시 명판을 끄고 켜십시오. 게임에서, 이러한 마커는 보이는 명판도 필요합니다.",
  ["highground.coachtargeting.try_following_your_own_target.acd537"] = "자신의 목표를 따라보세요",
  ["highground.coachtargeting.turn_sample_recommendations_off_the_sniper_marker.02c850"] = "예시 추천을 끄십시오. 저격수 표시가 현재 대상인 벡사로 이동합니다.",
  ["highground.coachtargeting.your_battleground_enemy_list.62d16e"] = "전장 적 목록",
  ["highground.coachtargeting.this_is_your_actual_enemy_panel_with.9e06eb"] = "이것은 예시 상대와 실제 적 패널입니다. 자세한 내용을 보려면 행을 마우스 오른쪽 버튼으로 클릭합니다. 게임에서, 왼쪽 클릭 대상 및 오른쪽 클릭은 주시 대상으로 적을 유지합니다.",
  ["highground.coachtargeting.sample_rows_do_not_change_your_target.7affdd"] = "예시 행은 대상 또는 주시 대상을 변경하지 않습니다. 패널 컨트롤은 실제 환경설정을 저장합니다.",
  ["highground.coachtargeting.enable_enemy_list_in_game.ba1d59"] = "게임에서 적 목록 사용하기",
  ["highground.coachtargeting.read_the_recommendation_rank.0f34cd"] = "추천 순위 읽기",
  ["highground.coachtargeting.the_rank_suggests_who_to_attack_now.24df75"] = "순위는 누구를 공격할지를 제안한다; NOW는 도달 가능한 제안을 표시한다. 행은 현재 모양 및 정렬 설정을 사용합니다.",
  ["highground.coachtargeting.if_you_have_hidden_rank_numbers_in.6c1e0c"] = "배틀그라운드 외관에서 계급 번호가 숨겨져 있다면 가이드는 대신 그 행을 강조합니다.",
  ["highground.coachtargeting.def_means_defense_active.f657f0"] = "DEF는 방어 활성화를 의미합니다",
  ["highground.coachtargeting.lunara_has_an_observed_defensive_ability_running.cef387"] = "루나라는 방어 능력이 뛰어나다. 실제 행은 DEF를 보여주고 그 내용을 어둡게 표시합니다.",
  ["highground.coachtargeting.status_labels_follow_your_battlegrounds_appearance_setting.ca7153"] = "상태 레이블은 Battlegrounds 외관 설정을 따릅니다. 다음은 그 방어가 끝나는 것을 보여준다.",
  ["highground.coachtargeting.the_defense_has_ended.eab6dc"] = "방어는 끝났습니다",
  ["highground.coachtargeting.lunara_s_defensive_ability_has_ended_spent.297484"] = "루나라의 방어 능력이 종료되었습니다. SPENT는 최근 변경 사항을 표시합니다; 당신은 여전히 공격할 때를 선택합니다.",
  ["highground.coachtargeting.spent_lasts_briefly_replay_shows_the_defense.870b3f"] = "SPENT는 짧게 지속된다. 리플레이는 방어가 다시 끝나는 것을 보여준다.",
  ["highground.coachtargeting.immune_means_damage_is_blocked.f27940"] = "면역은 피해가 차단됨을 의미합니다.",
  ["highground.coachtargeting.an_observed_immunity_prevents_damage_the_recommendation.2686ec"] = "관찰된 면역은 손상을 방지합니다. 권고는 면역이 끝날 때까지 이 적을 배제합니다.",
  ["highground.coachtargeting.cc_marks_breakable_crowd_control.5e7301"] = "CC는 깨지기 쉬운 군중 통제를 나타냅니다",
  ["highground.coachtargeting.attacking_this_enemy_may_break_the_effect.270e22"] = "이 적을 공격하면 효과가 깨집니다. 대상 행동 설정은 군중 제어를 유지할지 여부를 결정합니다.",
  ["highground.coachtargeting.unknown_distance_stays_unknown.01e741"] = "알 수 없는 거리가 알 수 없는 상태로 유지됨",
  ["highground.coachtargeting.the_distance_means_there_is_no_reliable.630799"] = "거리가 --이면 신뢰할 수 있는 거리 관측이 없다는 뜻입니다. 0미터라는 뜻이 아니며, 이 적은 도달 가능한 추천 대상이 될 수 없습니다.",
  ["highground.coachtargeting.spectag.title"] = "숨겨진 전문화 표시하기",
  ["highground.coachtargeting.spectag.text"] = "게임이 적의 전문화를 보여 주지 않으면 해당 줄에 마우스를 올리고 오른쪽의 전문화 아이콘 중 하나를 클릭하세요. Highground를 사용하는 팀원도 표시를 볼 수 있습니다. 표시된 아이콘을 다시 클릭하면 제거됩니다. 나중에 게임이 전문화를 확인하면 표시를 대체합니다.",
  ["highground.coachtargeting.spectag.hint"] = "Lunara에게 시험해 보세요. 예시 표시는 이 안내에만 남고 공유되지 않습니다.",
