  ["highground.coachtools.this_button_opens_the_game_s_own.386d0c"] = "이 버튼은 게임의 매크로 창을 엽니다. 저장된 매크로도 여기에 나타납니다.",
  ["highground.coachtools.click_open_wow_macros_or_continue_to.2d0cfe"] = "WoW 매크로 열기 를 클릭하거나 마지막 단계를 계속 읽으십시오.",
