  ["highground.coachtools.read_the_preset_s_purpose_ready_to.84c1f3"] = "사전 설정의 목적을 읽습니다. 사용할 준비가 되어 있다는 것은 주문이 배워졌다는 것을 의미하며, 배우지 않았다는 것은 아직 작동하지 않는다는 것을 의미한다.",
