  ["highground.coachtools.open_the_target_menu_focus_keeps_a.cc40a3"] = "대상 메뉴를 엽니다. 주시 대상은 두 번째 대상을 유지하며 마우스 오버는 포인터 아래의 단위를 사용합니다. 이것은 매크로의 버전을 미리 봅니다.",
  ["highground.coachtools.this_preset_has_a_fixed_target_there.01a659"] = "이 사전 설정에는 고정된 대상이 있으며 대상 메뉴가 없습니다.",
  ["highground.coachtools.a_focus_macro_needs_a_focus_set.332ba6"] = "주시 대상 매크로는 게임에서 먼저 주시 대상을 설정해야 합니다.",
  ["highground.coachtools.use_macro_saves_it_to_wow.24ba41"] = "매크로를 사용하여 WoW에 저장",
