  ["highground.coachtools.optional_this_is_a_real_save_button.43caf6"] = "선택사항: 이것은 실제 저장 버튼입니다. 다음은 저장하지 않고 계속됩니다.",
  ["highground.coachtools.create_a_spell_macro_with_casting_options.03eb6c"] = "캐스팅 옵션이 있는 주문 매크로 만들기",
