  ["highground.coachtools.this_cannot_guarantee_instant_only_casting_or.94311d"] = "이것은 인스턴트 캐스팅만을 보장하거나 프로세스를 검사할 수 없습니다. 게임에서 프로세서와 프로세서 없이 테스트. 만들기 를 열면 매크로가 저장되지 않으며 기존 초안이 유지됩니다.",
  ["highground.coachtools.drag_its_icon_onto_your_action_bar.6782f5"] = "아이콘을 작업 표시줄로 드래그합니다.",
