  ["highground.modules.recommended_remove_extra_standalone_addons.787e18"] = "추천: 추가 독립형 애드온 제거",
  ["highground.modules.highground_already_includes_these_remove_only_these.b1a936"] = "Highground에 이미 포함되어 있습니다. 다음 개별 다운로드만 제거하세요.\n{value2}.\n\n1. WoW를 종료하세요.\n2. 애드온 관리자에서 표시된 개별 다운로드를 제거하거나, 표시된 폴더만 삭제하세요.\n3. Highground를 다시 설치한 다음 WoW를 다시 시작하세요.\n\nHighground, 모든 HighgroundModule 폴더, HighgroundBountyData, HighgroundReputationData는 유지하세요. 두 데이터 애드온을 모두 활성화해 두어야 Highground를 불러올 수 있습니다.",
  ["highground.modules.highground_includes_all_six_features_no_standalone.3bf9dc"] = "Highground에는 여섯 가지 기능이 모두 포함되어 있습니다. 따로 다운로드할 필요가 없습니다. 함께 제공되는 모듈 폴더와 필수 데이터 애드온 두 개를 유지하세요. 이 스위치로 기능을 끈 다음 리로드하세요.",
  ["highground.modules.reload_to_apply.1f4e74"] = "적용하려면 새로 고침",
  ["highground.modules.reload_when_you_re_ready_to_apply.ae9dfa"] = "이러한 변경 사항을 적용할 준비가 되면 다시 로드합니다.",
  ["highground.modules.no_addon_changes_pending.184cb9"] = "보류 중인 애드온 변경 사항이 없습니다.",
  ["highground.navigation.included_with_highground_expand_for_its_overview.1a5d5a"] = "Highground에 포함되어 있습니다. 개요, 설정 및 가이드를 확장합니다.",
  ["highground.onboarding.this_panel_is_off_check_enable_in.102b57"] = "이 패널은 꺼져 있습니다. 시도하려면 가이드 아래의 게임에서 활성화를 확인하십시오.",
