  ["highground.users.channel_membership_does_not_confirm_a_responding.ee5706"] = "채널 멤버십은 응답하는 애드온 또는 그 버전을 확인하지 않습니다. 공지가 없는 회원은 별도로 표시됩니다. 사용할 수 없거나 불완전한 회원 목록은 최근 발표로 되돌아갑니다. 이것은 서버 인구 조사가 아닌 예시입니다. 그룹 및 길드 감지는 여전히 호환 가능한 Highground 발표가 필요합니다. 독립 실행형 릴리스는 자체 발견을 사용합니다.",
