  ["macros.buildoptions.adds_stopcasting_at_the_end_for_cast.e9b42b"] = "'주문 시전'의 끝에 /stopcasting을 추가합니다. 즉시 발동 효과가 터졌을 시점에 일반 시전을 취소하려 하지만 실제로 발동했는지는 확인하지 않습니다. 일부 클라이언트에서는 일반 시전이 계속될 수 있습니다. 진행 중인 시전이나 정신 집중을 끊을 수도 있습니다. 제자리에서 발동이 있을 때와 없을 때 모두 시험해 보세요.",
