  ["shared.form.use_your_target.b6c784"] = "목표물 사용",
  ["shared.form.copy_the_selected_player_s_exact_name.9fd7b9"] = "선택한 플레이어의 정확한 이름과 서버를 복사합니다. 친구 또는 플래그되지 않은 플레이어를 포함합니다. 이것은 이름만 채우고 아무것도 게시하지 않습니다.",
  ["shared.form.your_reward.fa1b16"] = "당신의 보상",
  ["shared.form.whole_gold_per_approved_kill_1_and.9b8724"] = "승인된 킬당 전체 골드; 1과 1g 모두 작동합니다. 총 약속은 요청된 모든 킬을 포함합니다. 계정 금 추적은 기본적으로 켜져 있으며 충분한 금을 요구하는 것은 기본적으로 꺼져 있습니다. 낮은 잔액은 입력하는 동안 경고되며 해당 요구 사항이 활성화된 경우에만 생성을 차단합니다. 기존 약속은 사용 가능한 총액을 줄입니다.",
