  ["shared.form.use_30m_2h_or_7d_allowed_range.2981b0"] = "30m, 2h 또는 7d를 사용합니다. 허용 범위: 5 분에서 30 일. 다른 게시자는 자신의 만료일을 선택합니다. 편집은 활성화된 약속을 연장할 수 있지만 단축할 수는 없습니다.",
