  ["shared.previewsamples.spot_a_wanted_player.3f246b"] = "현상 수배 플레이어 찾기",
  ["shared.previewsamples.see_the_wanted_popup_portrait_nearby_highlight.04e33a"] = "현상 수배 팝업, 인물, 인근 하이라이트 및 명판 동전을 참조하십시오. 재생은 사용자의 사운드 환경설정을 사용합니다.",
  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "인물 사진은 선택한 플레이어 또는 캐릭터를 라벨화된 예로 사용합니다. 이것은 결코 그들에게 보상을 두지 않습니다. 라이브 알림은 목표물, 마우스 오버 및 명판을 포함한 관측에서 발생합니다.",
  ["shared.previewsamples.wanted_board.b69f07"] = "현상 수배 게시판",
  ["shared.previewsamples.wanted_cards_and_full_posters.c0244c"] = "현상 수배 카드 및 전체 전단",
  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "현상 수배 카드를 클릭하거나 현상금 보기를 클릭하여 각 기여자, 약관, 자금 및 만료를 확인하십시오. 새로 고침은 예시 보상이 도착하는 동안 비활성화된 버튼과 로더를 보여줍니다.",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "추적 시작은 내 현상금에 목표를 추가합니다. 킬이 감지되면 보고서 보기 에서 상태가 열립니다. 포스터는 목표와 보상을 먼저 두고, 세부 사항을 위해 양피지 너비를 사용하고 필요할 때 스크롤합니다. 사용할 수 없는 초상화는 라벨이 붙여져 있습니다.",
  ["shared.previewsamples.create_terms.1ea507"] = "항목 만들기( T)",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "예시 현상금 만들기",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "대상, 보상, 검토의 세 단계입니다. 마지막 확인 전에는 아무것도 저장되지 않습니다. 기본값은 어떤 방식이든 1회 처치입니다.",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "투어에 반환 저장. 공유는 선택 사항입니다. 개인 추적은 제로 골드를 사용할 수 있으며, 공유 보상은 양의 금액과 만료일이 필요합니다. 선호하는 마무리 게시자의 검토를 필요로합니다. 살아있는 보상은 생성되지 않습니다.",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "캐릭터 전반에 걸쳐 골드 사용",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "예시 지갑과 가방 골드 툴팁을 참조하십시오. 두 스위치를 모두 시도한 다음 & 조건 생성에서 사용 가능한 금액보다 큰 보상을 입력하십시오.",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "계정 추적은 기본적으로 켜져 있습니다. 충분한 골드 요구는 기본적으로 꺼져 있습니다. 예산을 넘는 보상은 경고가 표시되지만 만들 수 있습니다. 잔액은 이 서버 또는 Forever 서버 그룹 기준입니다. 부캐릭터 잔액은 로그인할 때 갱신되며, 지급과 이체는 직접 해야 합니다.",
  ["shared.previewsamples.guild_approval.d5172b"] = "길드 승인",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "길드 현상금 제출 및 승인",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "승인을 기다리는 시도, 장교 승인 및 거부, 그 다음 결과 현상 수배 카드를 검사. 이러한 역할은 길드 없이도 투어에서 사용할 수 있습니다.",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "승인된 길드 보상은 새로운 보상 포스터를 표시할 수 있습니다. 이것은 보상을 발표합니다, 관측이 아닙니다. 길드와 글로벌 게시판 모두와 보상을 공유하는 것은 두 번째 지불 의무를 생성하지 않습니다. Forever에서는 커뮤니티 보상이 규칙의 구성원과만 동기화됩니다.",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "공유 도착",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "귀하의 필터와 일치하는 보상",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "들어오는 포스터에서 추적 시작 또는 무시 를 사용합니다. 예시 알림 설정 및 자금 조달 상태를 시도해 보십시오. 이 목표물은 발견되지 않았습니다.",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "알림 최소는 현재 사용 가능한 자금 보고서와 보상을 계산합니다. 가져온, 낡은 또는 자금이 없는 제안은 구별할 수 있습니다. 추적은 금을 약속하지 않습니다. 무시하면 대상의 보상과 발견 경고를 묵살합니다.",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "현상금의 공동 상금을 성장",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "예시 기여를 추가하고, 원본 게시자의 조건을 검토하고, 통합 보상 업데이트를 확인하세요.",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "약관을 수락하는 것은 원래 게시자가 청구가 적격인지 여부를 결정하는 것을 의미합니다. 기여자는 동일한 허용된 현상금 사냥꾼에게 그들의 금액을 빚진다. 골드는 애드온에 의해 보유되거나 전송되지 않습니다.",
  ["shared.previewsamples.share_import.d10b63"] = "공유( G) 가져오기",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "현상금 링크 복사 및 가져오기 검토",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "애드온 외부의 공유는 선택 사항입니다. 글로벌, 길드 또는 개인 현상금 링크를 복사한 다음 예시 가져오기를 검토합니다.",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "복사할 링크 선택을 선택하고 Ctrl+C을 눌러 현상금 링크를 보냅니다. 수신자는 현상금 가져오기를 선택합니다. 채팅에서 공유는 개인 및 그룹 현상금에 사용할 수 있습니다. Discord 채널은 공유 게시판 대상을 별도로 엽니다. 투어 링크는 투어 외부에서 의도적으로 유효하지 않습니다.",
  ["shared.previewsamples.kills_reports.48e18a"] = "죽음 (보고서)",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "감지된 킬은 자동으로 보고서를 생성",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "예시 보고서 보기 를 사용하여 검토를 따릅니다. 반복 죽음과 스크린 샷 성공, 실패 또는 다시 시도를 시도하십시오. 복사 증명은 선택 사항입니다.",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "읽을 수 있는 죽음의 충격은 지역에서 확인되었습니다. 명예의 전당에 헌액된 사람은 다음을 포함할 수 있다. 스크린샷 체크표시는 이미지만 저장되었음을 확인합니다. 보상 승인 및 지불은 별도로 유지되며 수동 보고는 놓친 감지에 대한 것입니다. 이 투어는 스크린샷을 찍지 않습니다.",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "검토 및 지불을 통해 보고서 추적",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "검토 중, 승인, 지불 및 거부된 현상금 사냥꾼 및 게시자 예제를 찾아보십시오. 예시 게시자로 승인, 거부 및 마크 지불을 시도하십시오.",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "현상금 사냥꾼은 자신의 보고서를 승인할 수 없습니다. 게시자는 증거를 검토하고 게임을 통해 수동으로 지불한 다음 지불을 기록합니다. 반복 킬은 같은 보상을 두 번 지불하지 않고 다중 킬 목표에 포함될 수 있습니다.",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "사망 보고서에 의해 제안된 적들 검토",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "예시 보고서를 검사하고, 미리 채워진 보상을 검토하고, 제안을 거부하거나 적을 무시하십시오.",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "제안은 설정된 창에서 죽음과 참여 길드 보고서를 결합합니다. 서버에 의해 검증된 킬 증거가 아닌 검토를 위한 리드입니다. 공개 범위를 선택하고 저장하기 전까지는 아무것도 게시되지 않습니다.",
